	@Test
	void correlatedDistinctWitnessesPreserveDefaultAndNamedGraphScope() throws Exception {
		openStoreWithSelectedTypeAdjacency();

		String defaultExists = PREFIX
				+ "SELECT DISTINCT ?s WHERE { ?s a ex:CommonType . ?s ex:hasRole ?role . "
				+ "FILTER EXISTS { ?s ex:memberOf ex:GroupA } }";
		String defaultNotExists = PREFIX
				+ "SELECT DISTINCT ?s WHERE { ?s a ex:CommonType . ?s ex:hasRole ?role . "
				+ "FILTER NOT EXISTS { ?s ex:memberOf ex:GroupA } }";
		String namedExists = PREFIX
				+ "SELECT DISTINCT ?g ?s WHERE { GRAPH ?g { ?s a ex:CommonType . ?s ex:hasRole ?role . "
				+ "FILTER EXISTS { GRAPH ?g { ?s ex:memberOf ex:GroupA } } } }";
		String namedNotExists = PREFIX
				+ "SELECT DISTINCT ?g ?s WHERE { GRAPH ?g { ?s a ex:CommonType . ?s ex:hasRole ?role . "
				+ "FILTER NOT EXISTS { GRAPH ?g { ?s ex:memberOf ex:GroupA } } } }";

		assertParity(defaultExists, List.of("alice"));
		assertParity(defaultNotExists, List.of("bob", "carol"));
		assertParity(namedExists, List.of("g1|alice"));
		assertParity(namedNotExists, List.of("g2|bob"));
	}

	private void openStoreWithSelectedTypeAdjacency() throws Exception {
		store = new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc,ospc")
						.setNativeEvaluationEnabled(true)
						.setDirectAdjacencyEnabled(true)
						.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
						.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.SELECTED)
						.setDirectAdjacencyPredicates(List.of(RDF.TYPE))
						.setDirectAdjacencyBuildOnStart(true));
		repository = new SailRepository(store);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI alice = vf.createIRI(NS, "alice");
			IRI bob = vf.createIRI(NS, "bob");
			IRI carol = vf.createIRI(NS, "carol");
			IRI commonType = vf.createIRI(NS, "CommonType");
			IRI memberOf = vf.createIRI(NS, "memberOf");
			IRI hasRole = vf.createIRI(NS, "hasRole");
			IRI groupA = vf.createIRI(NS, "GroupA");
			IRI groupB = vf.createIRI(NS, "GroupB");
			IRI roleOne = vf.createIRI(NS, "RoleOne");
			IRI roleTwo = vf.createIRI(NS, "RoleTwo");
			IRI g1 = vf.createIRI(NS, "g1");
			IRI g2 = vf.createIRI(NS, "g2");
			connection.begin();
			connection.add(alice, RDF.TYPE, commonType);
			connection.add(bob, RDF.TYPE, commonType);
			connection.add(carol, RDF.TYPE, commonType);
			// Multiple role bindings duplicate Alice in the input so DISTINCT is part of the tested semantics.
			connection.add(alice, hasRole, roleOne);
			connection.add(alice, hasRole, roleTwo);
			connection.add(bob, hasRole, roleOne);
			connection.add(carol, hasRole, roleOne);
			connection.add(alice, memberOf, groupA);
			connection.add(alice, RDF.TYPE, commonType, g1);
			connection.add(alice, hasRole, roleOne, g1);
			connection.add(alice, hasRole, roleTwo, g1);
			connection.add(alice, memberOf, groupA, g1);
			connection.add(bob, RDF.TYPE, commonType, g2);
			connection.add(bob, hasRole, roleOne, g2);
			connection.add(bob, hasRole, roleTwo, g2);
			connection.add(bob, memberOf, groupB, g2);
			// The same subject has a positive witness in another graph, but no type statement in that graph.
			connection.add(alice, memberOf, groupA, g2);
			connection.commit();
		}
		assertThat(store.awaitDirectAdjacencyReady(30, java.util.concurrent.TimeUnit.SECONDS))
				.as("the fixture must publish the selected type view before native evaluation")
				.isTrue();
	}

	private void assertParity(String queryText, List<String> expectedRows) {
		List<String> expected = expectedRows.stream().sorted().toList();
		List<String> generic = evaluate(queryText, false).stream().sorted().toList();
		assertThat(generic).containsExactlyElementsOf(expected);
		List<String> nativeRows = evaluate(queryText, true);
		assertThat(nativeRows.stream().sorted().toList()).containsExactlyElementsOf(expected);
	}

	private List<String> evaluate(String queryText, boolean nativeEnabled) {
		String previousNative = System.getProperty(NATIVE_ENGINE_PROPERTY);
		set(NATIVE_ENGINE_PROPERTY, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(QueryLanguage.SPARQL, queryText);
			try (TupleQueryResult result = query.evaluate()) {
				List<String> rows = new ArrayList<>();
				while (result.hasNext()) {
					BindingSet bindings = result.next();
					String subject = bindings.getValue("s").stringValue().substring(NS.length());
					String graph = bindings.hasBinding("g")
							? bindings.getValue("g").stringValue().substring(NS.length()) + "|"
							: "";
					rows.add(graph + subject);
				}
				return rows;
			}
		} finally {
			restore(NATIVE_ENGINE_PROPERTY, previousNative);
		}
	}

	private void set(String property, String value) {
		System.setProperty(property, value);
	}

	private static void restore(String property, String value) {
		if (value == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, value);
		}
	}
